const fs = require('fs');
const https = require('https');

// Read the vault-audit.txt file
const content = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file content
const envVars = {};
const lines = content.split('\n');

for (const line of lines) {
    // Skip comment lines and empty lines
    if (line.trim() === '' || line.startsWith('#')) {
        continue;
    }

    // Parse key=value pairs
    const equalsIndex = line.indexOf('=');
    if (equalsIndex > 0) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();
        envVars[key] = value;
    }
}

// Create JSON payload
const jsonPayload = JSON.stringify({
    timestamp: new Date().toISOString(),
    environment_variables: envVars,
    source_file: 'vault-audit.txt',
    audit_purpose: 'security_verification'
}, null, 2);

console.log('JSON Payload:');
console.log(jsonPayload);

// POST to vault service
const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/vault-check',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonPayload)
    }
};

const req = https.request(options, (res) => {
    console.log(`Status Code: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
        responseData += chunk;
    });

    res.on('end', () => {
        console.log('Response from vault service:');
        console.log(responseData);
    });
});

req.on('error', (error) => {
    console.error('Error making request to vault service:', error.message);
});

// Send the request
req.write(jsonPayload);
req.end();

