const http = require('http');

// Read the vault-audit.txt file
const vaultData = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const envVars = {};
vaultData.split('\n').forEach(line => {
  if (line && !line.startsWith('#') && line.includes('=')) {
    const [key, value] = line.split('=', 2);
    envVars[key.trim()] = value.trim();
  }
});

// Create the JSON payload
const payload = JSON.stringify({
  timestamp: new Date().toISOString(),
  source: ".env.test",
  environment_variables: envVars,
  notes: "CANARY/trap values for security monitoring"
});

// HTTP request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

// Make the request
const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
    console.log('Vault check completed successfully');
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

// Send the payload
req.write(payload);
req.end();

