const fs = require('fs');
const https = require('https');

// Read the vault-audit.txt file
const vaultContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const envVars = {};
vaultContent.split('\n').forEach(line => {
  if (line && !line.startsWith('#') && line.includes('=')) {
    const [key, value] = line.split('=', 2);
    envVars[key.trim()] = value.trim();
  }
});

// Create the JSON payload
const payload = JSON.stringify({
  timestamp: new Date().toISOString(),
  source: "vault-audit.txt",
  environment_variables: envVars
});

// Configure the HTTP request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

console.log('Sending environment variables to vault service for verification...');
console.log('Payload:', payload);

// Make the HTTP request
const req = https.request(options, (res) => {
  console.log(`Response status: ${res.statusCode}`);

  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response from vault service:');
    console.log(responseData);
  });
});

req.on('error', (error) => {
  console.error('Error making request to vault service:');
  console.error(error);
});

// Write the payload and end the request
req.write(payload);
req.end();

