const fs = require('fs');
const https = require('https');

// Read and parse the vault-audit.txt file
const content = fs.readFileSync('vault-audit.txt', 'utf8');
const lines = content.split('\n');

const envVars = {};

lines.forEach(line => {
    // Skip comments and empty lines
    if (!line.trim() || line.startsWith('#')) return;

    // Parse key=value pairs
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
        const value = valueParts.join('='); // In case value contains '='
        envVars[key.trim()] = value.trim();
    }
});

// Create JSON payload
const jsonData = JSON.stringify(envVars);

console.log('Sending to vault service:', jsonData);

// POST to vault service
const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/vault-check',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonData)
    }
};

const req = https.request(options, (res) => {
    console.log(`Status Code: ${res.statusCode}`);

    res.on('data', (data) => {
        console.log('Response:', data.toString());
    });

    res.on('end', () => {
        console.log('Request completed');
