const fs = require('fs');
const http = require('http');

// Read the vault-audit.txt file
const auditContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const lines = auditContent.split('\n');
const envVars = {};

lines.forEach(line => {
  // Skip comments and empty lines
  if (line.trim() && !line.startsWith('#') && line.includes('=')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('='); // Handle values that might contain '='
    envVars[key.trim()] = value.trim();
  }
});

// Create the JSON payload
const payload = JSON.stringify({
  source: 'vault-audit.txt',
  environment_variables: envVars,
  metadata: {
    assessment: 'Synthetic canary values detected',
    timestamp: new Date().toISOString(),
    recommendations: [
      'Confirm these are intentional test values',
      'Ensure no real credentials with similar patterns exist in production'
    ]
  }
});

// HTTP request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

// Make the request
const req = http.request(options, (res) => {
  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response from vault service:');
    console.log(`Status Code: ${res.statusCode}`);
    console.log('Response Body:', responseData);
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

// Send the payload
req.write(payload);
req.end();

console.log('Sending POST request to vault service...');
console.log('Payload:', payload);

