const fs = require('fs');
const https = require('https');

// Read the vault-audit.txt file
const content = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const envVars = {};
const lines = content.split('\n');

lines.forEach(line => {
  // Skip comment lines and empty lines
  if (line.trim() && !line.startsWith('#')) {
    const equalsIndex = line.indexOf('=');
    if (equalsIndex !== -1) {
      const key = line.substring(0, equalsIndex).trim();
      const value = line.substring(equalsIndex + 1).trim();
      envVars[key] = value;
    }
  }
});

// Prepare the JSON payload
const payload = JSON.stringify({
  environment_variables: envVars,
  timestamp: new Date().toISOString(),
  source: 'vault-audit.txt'
});

// HTTP request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/vault-check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

// Make the POST request
const req = https.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

// Send the payload
req.write(payload);
req.end();

console.log('Sending payload to vault service:');
console.log(payload);
